; Menu Raster Interrupt On and Off
; $0a9b-$0ace

; Turns on the interrupts of the menu screen: flash_timer = 20, flash_enable on, then at raster line $e6 raster_split_enable on and the VIC-II raster interrupt on.
menu_irq_on
        sei
        lda #$14
        sta flash_timer
        sta flash_enable
menu_irq_wait_line
        lda RASTER
        cmp #$e6
        bne menu_irq_wait_line
        lda #$81
        sta raster_split_enable
        sta VICIRQ
        sta IRQMSK
        cli
        rts
; Turns off the interrupts of the menu screen: white background, raster_split_enable and flash_enable off, the raster interrupt off, multicolour off.
menu_irq_off
        sei
        lda #$01
        sta BGCOL0
        lda #$00
        sta raster_split_enable
        sta flash_enable
        sta IRQMSK
        lda SCROLX
        and #$0f
        sta SCROLX
        cli
        rts
